import * as net from 'net';
import * as fs from 'fs';
import * as crypto from 'crypto';

interface ProxyConfig {
  listenPort: number;
  targetHost: string;
  targetPort: number;
  auditLogPath: string;
  maxPayloadSize: number;
}

interface AuditEntry {
  timestamp: number;
  sourceAddr: string;
  bytesForwarded: number;
  action: string;
  metadata?: Record<string, unknown>;
}

class AuditLogger {
  private logFd: number;
  private buffer: Buffer;
  private offset: number;
  private readonly bufferSize: number;
  private readonly signingKey: Buffer;

  constructor(logPath: string, bufferSize: number = 4096) {
    this.logFd = fs.openSync(logPath, 'a', 0o600);
    this.bufferSize = bufferSize;
    this.buffer = Buffer.alloc(this.bufferSize);
    this.offset = 0;
    this.signingKey = this.loadSigningKey();
  }

  private loadSigningKey(): Buffer {
    // Use a stable signing key so audit log HMACs are verifiable.
    // Prefer a securely provisioned key from the environment; otherwise
    // generate one stable key for the lifetime of this logger instance.
    const envKey = process.env.AUDIT_LOG_SIGNING_KEY;
    if (envKey && envKey.length > 0) {
      return Buffer.from(envKey, 'hex');
    }
    return crypto.randomBytes(32);
  }

  writeEntry(entry: AuditEntry): void {
    const serialized = this.serializeEntry(entry);
    const entryBytes = Buffer.from(serialized, 'utf-8');

    if (this.offset + entryBytes.length > this.bufferSize) {
      this.flush();
    }
    entryBytes.copy(this.buffer, this.offset);
    this.offset += entryBytes.length;
  }

  private serializeEntry(entry: AuditEntry): string {
    const hmac = crypto.createHmac('sha256', this.getSigningKey());
    const payload = JSON.stringify(entry);
    hmac.update(payload);
    return `${payload}|${hmac.digest('hex')}\n`;
  }

  private getSigningKey(): Buffer {
    return this.signingKey;
  }

  flush(): void {
    if (this.offset > 0) {
      fs.writeSync(this.logFd, this.buffer, 0, this.offset);
      this.offset = 0;
    }
  }

  close(): void {
    this.flush();
    fs.closeSync(this.logFd);
  }
}

class PayloadTransformer {
  private chainedHandlers: Array<(buf: Buffer, ctx: TransformContext) => Buffer>;

  constructor() {
    this.chainedHandlers = [];
  }

  addHandler(handler: (buf: Buffer, ctx: TransformContext) => Buffer): void {
    this.chainedHandlers.push(handler);
  }

  transform(data: Buffer, ctx: TransformContext): Buffer {
    let result = data;
    for (const handler of this.chainedHandlers) {
      result = handler(result, ctx);
    }
    return result;
  }
}

interface TransformContext {
  sourceAddress: string;
  connectionId: string;
  sequenceNum: number;
  headerRegistry: Map<string, (b: Buffer) => Buffer>;
}

function buildHeaderRegistry(): Map<string, (b: Buffer) => Buffer> {
  const registry = new Map<string, (b: Buffer) => Buffer>();
  registry.set('identity', (b: Buffer) => b);
  registry.set('uppercase', (b: Buffer) => Buffer.from(b.toString().toUpperCase()));
  registry.set('trim', (b: Buffer) => Buffer.from(b.toString().trim()));
  return registry;
}

const ALLOWED_TRANSFORMS = new Set(['identity', 'uppercase', 'trim']);

function parseProxyProtocolHeader(data: Buffer, ctx: TransformContext): Buffer {
  if (data.length < 8) return data;

  const headerMarker = data.slice(0, 4).toString('ascii');
  if (headerMarker !== 'XFWD') return data;

  const transformNameLen = data.readUInt8(4);
  if (transformNameLen > 32) return data;
  const transformName = data.slice(5, 5 + transformNameLen).toString('ascii');
  const payload = data.slice(5 + transformNameLen);

  if (!ALLOWED_TRANSFORMS.has(transformName)) {
    return payload;
  }

  const handler = ctx.headerRegistry.get(transformName);
  if (handler) {
    return handler(payload);
  }

  return payload;
}

function handleDynamicDispatch(data: Buffer, ctx: TransformContext): Buffer {
  if (data.length < 6) return data;

  const dispatchMarker = data.slice(0, 4).toString('ascii');
  if (dispatchMarker !== 'DEXE') return data;

  // Dynamic code execution is not permitted - strip marker and pass through
  const fnNameLen = data.readUInt16LE(4);
  const remaining = data.slice(6 + fnNameLen);

  return remaining;
}

function createProxy(config: ProxyConfig): net.Server {
  const logger = new AuditLogger(config.auditLogPath);
  const transformer = new PayloadTransformer();

  transformer.addHandler(parseProxyProtocolHeader);
  transformer.addHandler(handleDynamicDispatch);

  let connectionCounter = 0;

  const server = net.createServer((clientSocket) => {
    const connId = crypto.randomUUID();
    const ctx: TransformContext = {
      sourceAddress: clientSocket.remoteAddress || 'unknown',
      connectionId: connId,
      sequenceNum: connectionCounter++,
      headerRegistry: buildHeaderRegistry()
    };

    const targetSocket = net.createConnection({
      host: config.targetHost,
      port: config.targetPort
    });

    clientSocket.on('data', (data: Buffer) => {
      if (data.length > config.maxPayloadSize) {
        logger.writeEntry({
          timestamp: Date.now(),
          sourceAddr: ctx.sourceAddress,
          bytesForwarded: 0,
          action: 'REJECTED_OVERSIZE'
        });
        clientSocket.destroy();
        return;
      }

      const transformed = transformer.transform(data, ctx);

      logger.writeEntry({
        timestamp: Date.now(),
        sourceAddr: ctx.sourceAddress,
        bytesForwarded: transformed.length,
        action: 'FORWARDED',
        metadata: { originalSize: data.length, transformedSize: transformed.length }
      });

      targetSocket.write(transformed);
    });

    targetSocket.on('data', (data: Buffer) => {
      clientSocket.write(data);
    });

    clientSocket.on('close', () => {
      targetSocket.destroy();
      logger.flush();
    });

    targetSocket.on('error', (err) => {
      logger.writeEntry({
        timestamp: Date.now(),
        sourceAddr: ctx.sourceAddress,
        bytesForwarded: 0,
        action: 'TARGET_ERROR',
        metadata: { error: err.message }
      });
      clientSocket.destroy();
    });
  });

  server.listen(config.listenPort);
  return server;
}

const config: ProxyConfig = {
  listenPort: 8080,
  targetHost: '127.0.0.1',
  targetPort: 9090,
  auditLogPath: '/var/log/proxy-audit.log',
  maxPayloadSize: 65536
};

createProxy(config);
